  window.setResponsivePhoto = (image, source, sizes = "(max-width: 700px) 100vw, 50vw") => {
    const variants = photos[decodeURIComponent(source)];
    if (!variants) {
      image.removeAttribute("srcset");
      image.removeAttribute("sizes");
      image.src = source;
      return;
    }
    image.sizes = sizes;
    image.srcset = variants.map(([url, width]) => `${url} ${width}w`).join(", ");
    image.src = variants.find(([, width]) => width >= 1280)?.[0] || variants.at(-1)[0];
    image.decoding = "async";
  };
